DATA=[
dict(path='/treatment-costs/urinary-catheter-reimbursement-update',slug='urinary-catheter-reimbursement-update',cat='치료비',title='자가도뇨카테터 요양비, 현재 기준과 12월 확대 계획 비교',desc='자가도뇨카테터의 현행 일 9천 원·최대 6개 기준과 12월 확대 추진안을 나눠 봅니다. 소아·성인 예정 금액, 공단 등록·처방·제품 구입과 청구서류 확인 순서입니다.',status='현행 지원 운영 중·확대안은 2026년 12월 추진 일정으로 발표',parent='/claims/medical-expense-claim-documents',parent_note='자가도뇨카테터 구입비는 병원 진료비 영수증만으로 처리하는 민간보험 청구와 절차가 다릅니다. 공단 요양비의 등록·처방·구입 증빙과 확대 예정 기준을 따로 확인하세요.',insurance=True,sources=[(CATH,'공단 자가도뇨 소모성재료 안내','현행 대상·금액·등록·처방과 청구서류'),(PLAN,'복지부 의료혁신 지원 발표','확대 정책과 추진 단계'),(PLANPDF,'정부 추진계획 원문 PDF','7쪽 시행 일정·15쪽 연령별 확대안')],body=[
h('먼저 현재 청구와 확대 예정 기준을 나눠 보세요')+p('자가도뇨카테터를 구입할 예정이라면 공단 급여대상자 등록과 처방 여부부터 확인하세요. 현재 공단 안내는 하루 기준금액 9,000원, 1일 최대 6개를 제시합니다. 정부가 발표한 소아·성인 지원 확대는 2026년 12월 추진 일정이며, 발표된 금액으로 지금 바로 청구할 수 있다는 뜻은 아닙니다.')+p(a(CATH,'공단 현행 안내')+'와 '+a(PLANPDF,'정부 추진계획 7·15쪽')+'의 역할이 다릅니다. 예정 시행월이 가까워져도 실제 구입일에 적용되는 개정 기준·등록 내역·처방을 공단에 확인하고 구입량을 정하세요. 사용 횟수와 방법은 담당 의료진에게 교육받아야 합니다.'),
h('소아와 성인의 확대안은 금액과 개수가 다릅니다')+table(['구분','현행 공단 안내','정부 확대 추진안'],[['19세 미만','9,000원/일·최대 6개','18,000원/일·최대 8개'],['19세 이상','9,000원/일·최대 6개','13,500원/일·성인 최대 개수는 개정 기준 확인'],['시행 단계','기존 요양비 운영','2026년 12월 추진 일정']])+p('표의 금액은 매일 계좌에 입금되는 정액 수당이 아니라 지원을 계산할 때 쓰는 기준금액입니다. 현행 일반 건강보험 대상자는 실제 구입가가 기준 이내이면 그 구입가의 90%, 초과하면 기준금액의 90%를 안내합니다. 차상위 본인부담경감 대상자의 별도 기준도 공단에서 확인하세요.')+p('확대안에서 소아의 8개를 성인에게 그대로 적용하거나, 기준금액 전액이 누구에게나 지급된다고 읽지 않습니다. 개정 고시의 적용일·연령 산정 방식·처방 범위가 확인되기 전에는 예정안을 확정 청구 기준으로 쓰지 마세요.'),
h('등록 후 처방을 받고 등록 제품을 구입하는 순서입니다')+p('공단은 자가배뇨가 불가능한 신경인성 방광환자 중 정해진 상병·진단기준을 만족해 등록된 사람을 대상으로 안내합니다. 단순히 카테터를 사용한다는 사실만으로 대상이 되는 것은 아닙니다. 비뇨기과·재활의학과 등 진료에서 등록 신청과 필요한 검사 결과를 확인합니다.')+ul(['의료기관에서 급여대상자 등록 요건과 검사 자료 확인','공단 등록 완료와 적용일 확인','자가도뇨 소모성재료 처방전 발급','공단 등록 판매업소·등록 제품 확인 후 처방 범위 내 구입','구입 증빙을 갖춰 공단 요양비 청구'])+p('현행 안내는 등록 이후 처방받아 구입한 경우를 지원 대상으로 설명합니다. 먼저 대량 구매한 뒤 등록하면 모두 소급된다고 생각하지 마세요. 처방은 1회 최대 90일까지로 안내되며 실제 처방기간과 구입 가능 범위를 확인해야 합니다.'),
h('병원 서류와 판매업소 증빙을 따로 준비합니다')+table(['단계','확인할 자료','확인처'],[['최초·해당 재등록','급여대상자 등록 신청서·요류역학검사 결과 등','담당의·공단'],['구입·청구','처방전·요양비 지급청구서·세금계산서','의료기관·판매업소·공단'],['구입 증빙 내용','품명·수량·단가·판매업소 정보','판매업소']])+p('모든 사람에게 재등록이 반복되는 것은 아닙니다. 공단은 일부 후천성 척수손상 및 기타 질병 대상자의 재등록을 별도로 안내합니다. 본인 등록 종료일이나 재등록 대상 여부를 확인한 뒤 필요한 검사·서류만 준비하세요. 일반 병원비 청구 자료는 '+a('/claims/medical-expense-claim-documents','의료비 청구서류 안내')+'와 구분해 보세요.'),
h('구입 전에 공단과 판매업소에 물을 질문')+ul(['제 등록이 현재 유효하고 이번 구입일에 어느 기준이 적용되나요?','처방기간 안에서 지원되는 제품·개수와 판매업소 등록은 확인됐나요?','확대 시행 전후를 걸친 처방·구입은 어떤 기준으로 정산하나요?','제가 제출할 증빙과 접수 방식은 무엇인가요?'])+p('정부 발표의 평균 의료비 절감 추정치는 개인에게 보장되는 환급액이 아닙니다. 공단 요양비와 민간 실손보험의 보상은 계산 구조가 다르므로, 실손을 문의할 때는 공단 지급 내역과 실제 남은 부담을 보험사에 함께 설명하세요.'),
h('가상 예시: 11월 처방과 12월 확대 소식을 함께 들었다면')+p('보호자 A씨가 11월에 소아용 카테터 처방을 받았다고 가정합니다. A씨는 12월 확대 발표만 보고 개수를 늘려 사지 않고, 공단에 시행 여부와 처방·구입일별 적용 기준을 먼저 묻습니다. 이 예시는 확대안이 이미 시행됐거나 특정 구매가 승인됐다는 사례가 아닙니다.')+'<blockquote>자가도뇨 급여대상자로 등록돼 있습니다. 이번 처방·구입일에 적용되는 일일 기준금액과 개수, 등록 제품·판매업소 확인 방법, 제출할 청구서류를 안내해 주세요.</blockquote>']),
dict(path='/treatment-costs/glycogen-storage-glucose-supplies-support',slug='glycogen-storage-glucose-supplies-support',cat='치료비',title='당원병 혈당검사지·연속혈당센서 지원, 2027년 시행 계획 확인',desc='당원병 E74.0 환자의 혈당검사지·채혈침·연속혈당측정용 전극 지원 추진 내용을 정리합니다. 2027년 2분기 요양비와 질병관리청 본인부담 지원, 당뇨병 등록과의 차이를 설명합니다.',status='요양비는 2027년 2분기 예정·질병관리청 본인부담 지원은 별도 지침·시스템 준비',parent='/treatment-costs/diabetes-consumables-reimbursement-documents',parent_note='당뇨병 소모성재료 제도의 현재 대상에 당원병이 자동 포함되는 것은 아닙니다. 당원병의 2027년 지원 계획과 별도 등록·본인부담 지원을 구분해 확인하세요.',insurance=True,sources=[(KDCA,'질병관리청 당원병 지원 발표 PDF','요양비 시행 예정·별도 본인부담 지원 대상과 일정'),(PLANPDF,'건강보험 지원 확대 계획 원문','7·14쪽 대상·품목·기준금액과 시행 일정')],body=[
h('당원병 혈당관리 지원은 아직 시행 준비 단계입니다')+p('당원병 환자의 혈당검사지·센서 지원을 찾고 있다면 현재 구입분의 청구 가능 여부와 2027년 확대 계획을 먼저 구분하세요. 정부는 당원병 환자의 혈당측정검사지·채혈침·연속혈당측정용 전극을 요양비로 지원하는 방안을 2027년 2분기 시행 예정으로 발표했습니다. 현재 당뇨병 등록 절차를 그대로 밟으면 지원된다는 뜻은 아닙니다.')+p(a(KDCA,'질병관리청 9월 9일 발표')+'는 건강보험 요양비 적용과 별도로, 그 후 남는 본인부담금에 대한 희귀질환자 의료비 지원도 준비한다고 설명합니다. 구체적인 접수 일정·서식·대상자 연계는 이후 지침을 확인해야 합니다.'),
h('요양비와 본인부담 지원은 두 단계입니다')+table(['제도','발표된 대상·내용','발표된 시기'],[['건강보험 요양비 확대','E74.0 당원병 산정특례 등록자를 대상으로 혈당관리 품목 지원 추진','2027년 2분기 예정'],['희귀질환자 의료비 지원사업','환자가구 소득·재산 기준 등을 충족한 사람의 요양비 적용 후 본인부담 지원 추진','2027년 상반기 중 지침·시스템 개발 후 일정 확정'],['기존 특수식 구입비 지원','옥수수전분 등 별도 사업 기준 확인','혈당관리 신규 지원과 구분']])+p('요양비 대상이라는 사실만으로 별도 의료비 지원사업의 자격까지 갖추는 것은 아닙니다. 질병관리청 계획에는 환자가구 소득·재산 조건이 포함돼 있습니다. 부양의무자 기준 변경 예정 소식도 환자가구의 모든 조건이 없어진다는 뜻으로 읽지 마세요.'),
h('발표된 품목과 기준금액을 읽는 방법')+table(['품목','추진안의 기준금액','추진안의 본인부담'],[['혈당측정검사지·채혈침','1,300원/일','10%'],['연속혈당측정용 전극','10,000원/일','19세 미만 10%·19세 이상 20%']])+p('이 표는 정부 추진안의 구조를 설명하며 현재 구매분의 지급표가 아닙니다. 기준금액을 넘는 제품 가격이나 등록되지 않은 제품까지 모두 같은 비율로 지원된다는 뜻도 아닙니다. 전극 지원을 수신기·스마트폰·모든 센서 브랜드의 일괄 지원으로 확대해 해석하지 않습니다.')+p('제품 선택과 측정 결과 대응은 의료진에게 안내받으세요. 이 글은 센서 수치만으로 저혈당을 진단하거나 식사·약·옥수수전분 섭취 방법을 바꾸는 안내가 아닙니다.'),
h('당뇨병 등록과 희귀질환 산정특례를 혼동하지 마세요')+p('정부는 당원병 대상 질병코드 E74.0과 산정특례 등록을 지원 계획에 명시했습니다. 당뇨병과 마찬가지로 혈당을 측정한다는 이유로 당뇨병 진단·등록을 대신 신청하는 절차가 아닙니다. 본인의 정확한 질환·산정특례 등록 내역과 만료일을 의료기관·공단에 확인하세요.')+p('기존 당뇨병의 소모품 준비 절차는 '+a('/treatment-costs/diabetes-consumables-reimbursement-documents','당뇨병 소모성재료 요양비 서류')+'에서 볼 수 있으나, 당원병에 적용될 등록·처방·제품 요건은 시행 지침에서 따로 확인해야 합니다. 기존 희귀질환 산정특례 재등록도 신규 요양비 신청과 같은 절차가 아닙니다.'),
h('지금 준비할 자료와 시행 후 확인할 자료')+ul(['현재 당원병 진단·산정특례 등록 상태와 진료기관 확인','사용 중인 혈당관리 제품명·구입 주기·영수증 정리','공단의 시행 공고에서 적용일·등록·처방·제품 기준 확인','보건소에 별도 의료비 지원사업 자격·접수 일정 확인','기존 구매분의 소급 가능 여부는 공식 지침에서 따로 확인'])+p('미리 모은 영수증은 지출을 설명하는 자료일 뿐 향후 소급 지원을 보장하는 자료가 아닙니다. 확대를 기다리며 필요한 혈당관리를 임의로 중단하거나 지원될 것이라는 예상만으로 고가 제품을 먼저 계약하지 마세요.'),
h('가상 예시와 공단·보건소에 문의할 문장')+p('B씨 가족이 당원병 산정특례 등록은 되어 있지만 의료비 지원사업 신청은 하지 않았다고 가정합니다. 가족은 요양비 확대와 본인부담 지원의 자격·시작일을 각각 확인합니다. 산정특례 등록 하나로 모든 비용이 없어지는 사례가 아닙니다.')+'<blockquote>당원병 E74.0으로 산정특례 등록 중입니다. 혈당검사지·전극 요양비의 실제 시행일과 등록·처방 절차가 공고됐는지, 별도 본인부담 지원은 어디에 어떤 자격으로 신청하는지 알려 주세요.</blockquote>']),
dict(path='/treatment-costs/retevmo-ret-test-coverage',slug='retevmo-ret-test-coverage',cat='치료비',title='레테브모 급여, RET 융합 폐암과 RET 변이 갑상선 수질암 차이',desc='10월 1일 시행 레테브모 급여를 암종·RET 검사·치료차수로 나눠 봅니다. 폐암의 RET 융합과 갑상선 수질암의 RET 변이, 진행 시점과 이전 TKI 이력의 확인 순서입니다.',status='2026년 10월 1일 급여기준 시행·암종별 검사·진행 상태와 과거 치료 대조',parent='/guides/targeted-immunotherapy',parent_note='표적항암치료라도 약마다 검사·암종·치료차수가 다릅니다. 레테브모는 RET 융합 폐암과 RET 변이 갑상선 수질암의 급여 조건을 구분해 확인하세요.',insurance=True,sources=[(HIRA,'심평원 2026-210호 암 약제 급여 공고','10월 1일 시행 셀퍼카티닙 단독요법'),(ORIGINAL,'공고 원문 첨부 확인','폐암·갑상선암 투여대상과 주석'),(DRUGLIST,'심평원 약제 급여 목록','처방일의 등재·상한금액 확인 경로')],body=[
h('RET 검사명만으로 급여를 판단하지 않습니다')+p('레테브모캡슐의 성분은 셀퍼카티닙(selpercatinib)입니다. 2026년 10월 1일 급여기준이 신설됐지만 RET 결과가 있다는 사실만으로 어느 암에서나 같은 조건을 적용하지 않습니다. 비소세포폐암에서는 RET 융합, 갑상선 수질암에서는 RET 변이를 암종·진행 상태·치료이력과 함께 대조해야 합니다.')+p(a(HIRA,'심평원 공고 제2026-210호')+'의 단독요법 항목과 '+a(ORIGINAL,'공고 원문')+'을 기준으로 정리했습니다. 유전자 검사 용어는 진료실에서 결과지의 정확한 문구와 검사 방식을 확인하는 데 사용하고, 환자가 직접 약을 선택하는 기준으로 쓰지 마세요.'),
h('폐암과 갑상선 수질암의 확인 항목')+table(['확인 항목','비소세포폐암','갑상선 수질암'],[['RET 결과','RET 융합 양성','RET 변이'],['암종·상태','국소 진행성 또는 전이성·stage ⅢB 이상 비편평상피세포 조건','진행성 또는 전이성 수질암으로 전신요법 필요'],['치료단계','고식적 1차 이상','고식적 1차 이상'],['추가 조건','정확한 조직형·병기 대조','성인 및 만 12세 이상·14개월 이내 질병 진행 조건']])+p('일반적인 갑상선암 진단 전체를 수질암과 같게 취급하지 않습니다. 유두암·여포암 등 다른 조직형이나 다른 암종의 RET 결과에는 이 표를 그대로 적용하지 마세요. 공고의 허용 범위와 의약품 허가 범위도 서로 다른 문서이므로 의료진이 함께 확인해야 합니다.'),
h('이전 약제와 질병 진행 시점은 기록으로 확인하세요')+p('갑상선암 공고에는 레테브모 치료 후 실패한 경우 반데타닙 약값의 전액 본인부담 관련 문구와, 다른 TKI 실패 이력에 관한 주석이 있습니다. 후자의 괄호에는 진행성 분화 갑상선암에 한한다는 범위가 붙어 있으므로, 모든 수질암 환자에게 단순히 다른 TKI를 썼으면 불가라고 옮겨 읽지 않습니다.')+p('현재 질환이 수질암인지 분화 갑상선암인지, 과거 약제의 이름·목적·사용 기간과 질병 진행을 판단한 검사일을 의료진에게 전달하세요. 환자의 기억이나 약 봉투 개수만으로 차수·급여를 정하지 않습니다. 과거 치료를 중단한 이유가 부작용인지 질병 진행인지도 상담에서 구분해야 합니다.'),
h('유전자 검사결과와 비용 설명을 함께 요청합니다')+ul(['병리결과의 암종·조직형과 현재 병기 확인','RET 결과지의 융합·변이 구분 및 검사명 확인','이전 항암제·TKI 이름과 투여 시작·종료일 정리','갑상선 수질암은 진행 시점과 전신치료 필요성 확인','예정 처방일의 급여 항목·약제비·검사비를 나눠 문의'])+p('검사 비용의 급여 여부가 약의 급여 여부와 항상 같지는 않습니다. 추가 검사나 재검이 필요한지는 담당의가 판단합니다. 약제 상한금액에 복용량을 곱한 숫자만으로 개인의 전체 병원비를 계산하지 말고, 산정특례·다른 진료항목까지 나눈 설명을 받으세요.'),
h('표적항암 특약은 건강보험과 별도 확인합니다')+p('건강보험 급여 신설은 가입한 표적항암·항암약물치료 특약의 지급 확정과 다릅니다. 약관의 보장 정의와 진단·실제 처방·투여 기록을 보험사에 대조하세요. 허가된 약이라는 사실이나 RET 검사 양성만으로 보험금 지급을 단정하지 않습니다.')+p('치료 종류의 기본 차이는 '+a('/guides/targeted-immunotherapy','표적치료와 면역항암치료 안내')+'와 연결됩니다. 보험금 청구를 위해 유전자검사를 임의로 추가하거나 치료계획을 바꾸는 것이 아니라, 이미 정한 진료계획의 기록 중 필요한 범위를 확인하는 순서입니다.'),
h('가상 예시: 검사결과에 RET가 적혀 있다면')+p('C씨의 검사 결과지에 RET 관련 항목이 있고 레테브모를 상담한다고 가정합니다. C씨는 양성이라는 말만 전달하지 않고 암종·조직형과 융합인지 변이인지, 이전 치료와 진행 시점을 함께 확인합니다. 이 예시는 급여 승인이나 치료효과를 보장하지 않습니다.')+'<blockquote>제 조직형과 RET 결과가 어느 급여 항목에 해당하나요? 치료차수·이전 TKI 이력·진행 시점의 주석을 함께 대조하고, 약제와 검사 비용을 구분해 설명해 주세요.</blockquote>']),
dict(path='/treatment-costs/livdelzi-approval-coverage-check',slug='livdelzi-approval-coverage-check',cat='치료비',title='리브델지 허가, 원발성 담즙성 담관염 약값·보험 확인 순서',desc='10월 20일 허가된 리브델지의 성인 PBC 적응증을 UDCA 반응 불충분·내약성 문제로 나눠 봅니다. 허가와 실제 공급, 약값·건강보험·실손 확인은 별개입니다.',status='2026년 10월 20일 국내 품목허가 확인·공급·약가·개인 급여는 별도 확인',parent='/silbi/pharmacy-prescription-claim',parent_note='처방약 청구를 준비할 때 새 약의 국내 허가와 실제 공급·급여는 별도로 확인해야 합니다. 원발성 담즙성 담관염 리브델지의 허가 범위와 약값 확인 순서를 연결했습니다.',insurance=True,sources=[(LIV,'식약처 리브델지 품목허가 원문','허가일·성분·성인 PBC 적응증과 주의사항'),(DRUGLIST,'심평원 약제 급여 목록','현재 등재·상한금액과 적용일 확인')],body=[
h('리브델지가 허가됐어도 약값과 보험 적용은 따로 확인합니다')+p('리브델지캡슐은 원발성 담즙성 담관염(PBC) 성인 환자 치료에 쓰는 셀라델파 성분 의약품입니다. 식약처 품목정보에서 2026년 10월 20일 허가를 확인할 수 있습니다. 다만 국내 허가는 모든 병원에서 즉시 처방·조제가 가능하거나 건강보험 가격이 정해졌다는 뜻은 아닙니다.')+p(a(LIV,'식약처 품목허가 원문')+'의 대상과 주의사항을 진료 상담에서 확인하고, 병원·약국에 실제 공급과 비용을 따로 문의하세요. 품목정보의 보험약가 칸만으로 등재 상태를 확정하거나 해외 판매가를 국내 환자의 결제금액으로 옮기지 않습니다.'),
h('UDCA 반응과 내약성에 따라 허가된 사용 방식이 다릅니다')+table(['현재 치료 상황','허가 원문에서 확인하는 방식'],[['UDCA에 반응이 불충분한 성인 PBC','UDCA와 병용요법'],['UDCA에 내약성이 없는 성인 PBC','리브델지 단독요법'],['다른 간질환·다른 담관 질환','같은 조건을 임의로 적용하지 않음']])+p('내약성은 약의 부작용 등을 견딜 수 있는 정도를 말하며, 약효가 충분하지 않다는 말과 같지 않습니다. 어떤 상황에 해당하는지는 담당의가 기존 치료·검사 결과를 보고 판단합니다. 신약 허가 소식만으로 UDCA를 중단하거나 새 약을 추가하지 마세요.'),
h('담석·담도 폐색과 PBC는 같은 문제가 아닙니다')+p('PBC는 만성 간질환으로, 담석 제거술이나 일시적인 담도 폐색의 치료와 구분합니다. 담도 관련 증상이 있다는 이유만으로 이 약의 대상이 되지는 않습니다. 식약처 원문은 담관 폐색 환자의 사용을 피하도록 하고 금기·주의사항을 따로 제시합니다.')+p('또한 비대상성 간경화가 있거나 치료 중 발생한 환자에게 투여를 권장하지 않는다는 내용을 확인할 수 있습니다. 복수·출혈 등 증상이나 상태 판단은 의료진에게 맡기고, 해당 내용은 임의 복용을 막기 위한 상담 항목으로 읽으세요. 기존에 먹는 약·건강기능식품도 의료진·약사에게 알립니다.'),
h('가격을 물을 때는 공급·급여·실제 결제액을 나눕니다')+ul(['해당 병원이 리브델지를 실제 처방·공급할 수 있는지 확인','처방 예정일의 건강보험 등재와 세부 적용 조건 문의','약제비·진료·검사비를 구분한 비용 설명 요청','처방기간과 실제 조제량에 맞춘 약국 비용 확인','추가 비용이 있으면 전액본인부담·비급여 구분 문의'])+p('현재 확보한 공식 허가자료만으로 국내 출시일·실제 판매가·개인 급여를 확정할 수 없어 금액을 제시하지 않습니다. '+a(DRUGLIST,'심평원 급여 목록')+'의 최신 등재·시행일과 의료기관의 실제 처리 기준을 함께 확인하세요. 허가 단계의 불확실성을 비급여 확정이라는 말로 바꿔 쓰지도 않습니다.'),
h('실손은 처방 사실과 실제 부담 자료를 먼저 확인합니다')+p('실손 청구는 건강보험 급여와 별도 심사입니다. 가입 시기·약관·통원 및 처방조제 보장, 실제 부담액과 제외 조항을 보험사에 문의하세요. 희귀의약품이나 새 치료제라는 이유만으로 지급 또는 부지급을 단정할 수 없습니다.')+p('기본 준비는 '+a('/silbi/pharmacy-prescription-claim','약국 처방약 실비 청구 안내')+'에서 연결해 볼 수 있습니다. 처방전·약제비 계산서 등 보유한 자료를 먼저 보여 주고 필요한 추가 서류만 확인합니다. 해외 구매 영수증이나 개인 수입 비용을 국내 처방약 청구와 동일하게 처리한다고 가정하지 마세요.'),
h('가상 예시와 진료실·약국 질문')+p('D씨가 UDCA를 복용 중이며 새 약 허가 소식을 들었다고 가정합니다. D씨는 기존 약을 끊지 않고 담당의에게 반응 불충분 여부와 추가 치료 필요성을 묻습니다. 이후 공급 가능 시기와 실제 비용을 확인하는 사례이며, 새 약의 적합성·급여·실손 지급이 정해진 사례는 아닙니다.')+'<blockquote>제 상태가 허가된 성인 PBC 대상과 병용·단독 조건 중 어디에 해당하나요? 실제 공급 가능 여부, 처방일 급여와 약값, 필요한 검사 및 청구 자료를 나눠 안내해 주세요.</blockquote>']),
dict(path='/treatment-costs/qinlock-ripretinib-coverage-check',slug='qinlock-ripretinib-coverage-check',cat='치료비',title='퀸락정 리프레티닙 허가, GIST 4차 치료와 급여 확인법',desc='10월 16일 허가된 퀸락정의 성인 진행성 GIST 대상과 이전 키나아제 억제제 치료이력을 확인합니다. 4차 치료와 암 4기의 차이, 국내 공급·급여·약값 상담 자료를 정리했습니다.',status='2026년 10월 16일 국내 허가 확인·급여·공급·실제 약값은 별도 확인',parent='/guides/cancer-treatment-cost',parent_note='항암제 허가는 건강보험 등재·개인 비용과 다릅니다. GIST 퀸락정의 과거 치료 조건과 4차 치료·병기 구분, 약제비 상담 자료를 연결했습니다.',insurance=True,sources=[(QIN,'식약처 퀸락정 품목허가 원문','허가일·이매티닙 포함 이전 치료 조건·주의사항'),(DRUGLIST,'심평원 약제 급여 목록','등재·약가·적용일 확인 경로'),('https://www.hira.or.kr/bbsDummy.do?pgmid=HIRAA030023010000','심평원 암 약제 세부 급여기준','위장관기질종양 요법의 최신 공고 확인')],body=[
h('4차 치료는 암 4기라는 뜻이 아닙니다')+p('퀸락정50밀리그램은 리프레티닙 성분의 의약품으로, 식약처에서 2026년 10월 16일 국내 허가를 확인할 수 있습니다. GIST 4차 치료라는 표현은 이전 약제 치료 뒤 다음 치료를 검토하는 맥락이며, 암의 진행 정도를 뜻하는 4기와 같은 말이 아닙니다.')+p(a(QIN,'품목허가 효능·효과')+'는 이매티닙을 포함한 세 가지 이상의 키나아제 억제제로 치료받은 적이 있는 성인 진행성 위장관기질종양(GIST)을 대상으로 합니다. GIST 진단만 있거나 네 번째 진료를 받는다는 이유로 대상이 되는 것은 아닙니다.'),
h('과거 약 이름과 치료 경과를 정리해 의료진에게 보여 주세요')+table(['확인 항목','준비할 내용'],[['정확한 진단','위장관기질종양 여부·현재 진행 상태'],['이전 약제','이매티닙 포함 키나아제 억제제 이름'],['치료 시기','시작·종료일과 처방·진료기록'],['변경 이유','진행·부작용 등 담당의가 판단한 경과'],['현재 상담','다음 치료 적합성과 실제 공급 여부']])+p('허가 적응증의 세 가지 이상과 임상시험에 사용된 약제 목록을 같은 문장으로 바꾸지 않습니다. 원문의 임상시험에는 이매티닙·수니티닙·레고라페닙 이력이 설명되지만, 개인의 허가 범위는 효능·효과와 의료진 판단으로 대조해야 합니다. 복용약 개수나 약 이름 철자만으로 스스로 적용 여부를 결정하지 마세요.'),
h('허가·공급·건강보험·비용은 각각 확인해야 합니다')+p('허가는 해당 범위에서의 국내 의약품 사용을 심사한 결과입니다. 병원의 실제 도입·공급 일정이나 건강보험 급여 고시의 시행과는 단계가 다릅니다. 원문 품목정보와 현재 확인한 허가자료만으로 국내 출시일·확정 약가·개인 급여를 단정할 수 없어 특정 월 비용을 적지 않습니다.')+ul(['병원 약제부·담당의에게 실제 도입과 처방 가능 여부 문의','처방 예정일의 급여 등재·암 약제 세부 기준 확인','약제비·검사·진료 항목을 분리한 예상 비용 요청','산정특례 적용 범위와 별도 본인부담 항목 확인'])+p('조회할 때는 제품명 퀸락정과 성분명 리프레티닙을 함께 사용하세요. '+a(DRUGLIST,'약제 급여 목록')+'과 암 약제 공고는 서로 다른 확인 자료입니다. 허가자료의 보험약가 칸이 비어 있다는 한 가지 이유로 비급여 확정이라고 말하지 않습니다.'),
h('치료를 바꾸거나 용량을 조절하는 안내가 아닙니다')+p('식약처 원문은 항암제 사용 경험이 있는 의사의 감독하에 치료를 시작하고 모니터링하도록 안내합니다. 다른 약과의 상호작용, 혈압·심장 상태, 피부 변화·수술 계획 등은 의료진이 확인해야 합니다. 이 글에서는 개인이 따라 할 복용량·증량·중단 방법을 제시하지 않습니다.')+p('먹는 항암제라고 주사치료보다 간단하거나 안전하다고 판단하지 마세요. 현재 약·건강기능식품과 수술 예정 여부를 담당의·약사에게 알려 주세요. 새 약을 기다리며 기존 치료를 임의로 끊는 것도 피해야 합니다.'),
h('민간보험 문의는 실제 치료기록과 비용을 기준으로 합니다')+p('GIST 진단과 항암제 허가 사실이 특정 암·표적항암 담보 지급을 자동 확정하지 않습니다. 병리 진단, 가입 약관의 암·치료 정의, 실제 처방·투여 이력과 필요한 서류를 보험사에 확인하세요. 먹는 약이라는 이유만으로 제외되거나 포함된다고 일괄 단정하지 않습니다.')+p('전체 병원비를 나눠 보는 순서는 '+a('/guides/cancer-treatment-cost','암 치료비와 산정특례 안내')+'와 연결됩니다. 실손을 문의할 때도 공적 지원·급여 적용 후 실제 남은 부담과 약관상 보상 범위를 대조해야 합니다. 서류를 전부 새로 발급하기 전 접수처의 요구 목록을 확인하세요.'),
h('가상 예시: 여러 약을 쓴 뒤 퀸락정을 상담한다면')+p('E씨가 GIST로 여러 키나아제 억제제를 사용한 뒤 다음 치료를 상담한다고 가정합니다. E씨는 과거 약의 이름·기간·변경 이유를 정리해 의료진에게 보여 주고, 허가 범위와 공급·급여를 따로 묻습니다. 이는 처방·치료효과·보험금이 보장된 사례가 아닙니다.')+'<blockquote>제 이전 약제와 현재 진행 상태가 퀸락정 허가 범위에 해당하나요? 실제 도입·공급과 처방일 급여 기준, 약제비·검사비, 보험 문의용 기록을 나눠 설명해 주세요.</blockquote>'])
]
